CREATE TYPE "workout_status" AS ENUM ('in_progress', 'finished');
CREATE TABLE "exercises" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "slug" text NOT NULL UNIQUE, "name" text NOT NULL, "input_mode" text NOT NULL, "effective_weight_rule" text NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "workout_templates" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "slug" text NOT NULL UNIQUE, "name" text NOT NULL, "kind" text NOT NULL CHECK ("kind" IN ('lifting','cardio')), "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "template_exercises" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "template_id" uuid NOT NULL REFERENCES "workout_templates"("id") ON DELETE CASCADE, "exercise_id" uuid NOT NULL REFERENCES "exercises"("id"), "position" integer NOT NULL CHECK ("position" > 0), UNIQUE("template_id","position"));
CREATE TABLE "template_sets" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "template_exercise_id" uuid NOT NULL REFERENCES "template_exercises"("id") ON DELETE CASCADE, "position" integer NOT NULL CHECK ("position" > 0), "target_kind" text NOT NULL CHECK ("target_kind" IN ('reps','amrap')), "target_reps" integer CHECK ("target_reps" >= 0), "baseline_input_weight" double precision NOT NULL CHECK ("baseline_input_weight" >= 0), UNIQUE("template_exercise_id","position"));
CREATE TABLE "workout_instances" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "workout_date" text NOT NULL UNIQUE CHECK ("workout_date" ~ '^\\d{4}-\\d{2}-\\d{2}$'), "template_id" uuid REFERENCES "workout_templates"("id"), "template_slug" text NOT NULL, "template_name" text NOT NULL, "status" "workout_status" NOT NULL DEFAULT 'in_progress', "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "workout_exercises" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "workout_id" uuid NOT NULL REFERENCES "workout_instances"("id") ON DELETE CASCADE, "exercise_id" uuid REFERENCES "exercises"("id"), "exercise_slug" text NOT NULL, "name" text NOT NULL, "input_mode" text NOT NULL, "effective_weight_rule" text NOT NULL, "position" integer NOT NULL CHECK ("position" > 0), UNIQUE("workout_id","position"));
CREATE TABLE "workout_sets" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "workout_exercise_id" uuid NOT NULL REFERENCES "workout_exercises"("id") ON DELETE CASCADE, "position" integer NOT NULL CHECK ("position" > 0), "target_kind" text NOT NULL CHECK ("target_kind" IN ('reps','amrap')), "target_reps" integer CHECK ("target_reps" >= 0), "actual_reps" integer CHECK ("actual_reps" >= 0), "input_weight" double precision NOT NULL CHECK ("input_weight" >= 0), "effective_weight" double precision NOT NULL CHECK ("effective_weight" >= 0), "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE("workout_exercise_id","position"));
CREATE TABLE "cardio_activities" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "workout_id" uuid NOT NULL REFERENCES "workout_instances"("id") ON DELETE CASCADE, "position" integer NOT NULL CHECK ("position" > 0), "kind" text NOT NULL CHECK ("kind" IN ('treadmill','rowing','stairmaster')), "incline" double precision CHECK ("incline" >= 0), "speed" double precision CHECK ("speed" >= 0), "duration" text, "pace" text, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE("workout_id","position"));
CREATE TABLE "failed_passcode_attempts" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "identifier_hash" text NOT NULL, "attempted_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX "failed_attempt_identifier_time" ON "failed_passcode_attempts" ("identifier_hash", "attempted_at");
